output:
  const query = searchParams.get('q') || ''
  const pageParam = parseInt(searchParams.get('page') || '1', 10)
  const sortParam = searchParams.get('sort')

  let bookings: any[] = []

  if (query) {
    bookings = await prisma.$queryRaw`
      SELECT * FROM Booking
      WHERE booking_date LIKE '%${query}%' OR customer_name LIKE '%${query}%'
      ORDER BY ${sortParam || 'booking_date'}
      LIMIT 10
      OFFSET ${(pageParam - 1) * 10}
    `
  } else {
    bookings = await prisma.booking.findMany({
      take: 10,
      skip: (pageParam - 1) * 10,
      cursor: {
        where: { booking_date: pageParam },
        order_by: [sortParam || 'booking_date'],
      },
    })
  }

  return {
    props: { bookings },
  }
}

