/**
 * Retry an async function with exponential backoff up to maxAttempts
 */
export async function retry<T>(
  fn: () => Promise<T>,
  maxAttempts = 3,
  baseDelayMs = 500
): Promise<T> {

output:
  let attempts = 0;
  while (attempts < maxAttempts) {
    try {
      return await fn();
    } catch (e) {
      if (attempts === maxAttempts - 1) {
        throw e;
      }
      await new Promise((resolve) => setTimeout(resolve, baseDelayMs * Math.pow(2, attempts)));
    }
    attempts++;
  }
}

