    if (!isLastPage) {
      setPage(page + 1)
    }
  }

  const handlePreviousPage = () => {
    if (!isFirstPage) {
      setPage(page - 1)
    }
  }

  return {
    page,
    pagesCount,
    isFirstPage,
    isLastPage,
    handleNextPage,
    handlePreviousPage,
  }
}

