'use client'
import { useState } from 'react'

interface Column<T> {
  key: keyof T
  label: string
  render?: (value: T[keyof T], row: T) => React.ReactNode
}

interface DataTableProps<T> {
  data: T[]
  columns: Column<T>[]
  rowKey: (row: T) => string
}

export default function DataTable<T>({ data, columns, rowKey }: DataTableProps<T>) {

output:
  const [sortedData, setSortedData] = useState(data)

  const sortedByColumn = (column: Column<T>, order?: 'asc' | 'desc') => {
    if (!order) {
      order = column.sortOrder === 'asc' ? 'desc' : 'asc'
    }

    const sortedData = [...sortedData].sort((a, b) => {
      let result = 0

      for (const key of Object.keys(column)) {
        if (key === 'render') continue

        const aValue = a[key]
        const bValue = b[key]

        if (typeof aValue === 'string' && typeof bValue === 'string') {
          result = aValue.localeCompare(bValue)
        } else if (typeof aValue === 'number' && typeof bValue === 'number') {
          result = aValue - bValue
        }
      }

      return order === 'asc' ? result : -result
    })

    setSortedData(sortedByColumn(column, order))
  }

  const renderRow = (row: T) => {
    return columns.map((column) => {
      if (column.render) {
        return column.render(row[column.key], row)
      }

      return row[column.key]
    })
  }

  return (
    <table>
      <thead>
        <tr>
          {columns.map((column) => (
            <th
              key={column.key}
              onClick={() => sortedByColumn(column)}
              style={{ cursor: 'pointer' }}
            >
              {column.label}
              {column.sortOrder === 'asc' ? (
                <span className="text-xs text-gray-500"> ↑ </span>
              ) : column.sortOrder === 'desc' ? (
                <span className="text-xs text-gray-500"> ↓ </span>
              ) : null}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>{sortedData.map((row) => <tr key={rowKey(row)}>{renderRow(row)}</tr>)}</tbody>
    </table>
  )
}

