interface DropdownMenuProps {
  trigger: React.ReactNode
  items: { label: string; onSelect: () => void }[]
}

export default function DropdownMenu({ trigger, items }: DropdownMenuProps) {

output:
  const [show, setShow] = useState(false)

  const ref = useRef<HTMLDivElement>(null)

  const handleTriggerClick = () => {
    if (show) {
      setShow(false)
    } else {
      setShow(true)
    }
  }

  const handleDocumentClick = (e: any) => {
    if (!ref.current?.contains(e.target)) {
      setShow(false)
    }
  }

  return (
    <>
      <div ref={ref} onClick={handleTriggerClick}>
        {trigger}
      </div>

      {show && (
        <div className="absolute z-10 w-48 bg-white p-2 shadow-lg rounded-md">
          <ul>
            {items.map((item, index) => (
              <li key={index} onClick={item.onSelect}>
                {item.label}
              </li>
            ))}
          </ul>
        </div>
      )}

      <div className="fixed inset-0 z-10 bg-black opacity-50" onClick={handleDocumentClick} />
    </>
  )
}

