type EventMap = Record<string, unknown>

export class TypedEmitter<E extends EventMap> {

context.prefix:
// Type-safe event emitter — events typed as a record
type EventMap = Record<string, unknown>

export class TypedEmitter<E extends EventMap> {

output:
  private readonly listeners: Map<keyof E, Array<(value: E[keyof E]) => void>> = new Map()

  on<K extends keyof E>(
    event: K,
    listener: (value: E[K]) => void
  ): this {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, [])
    }

    this.listeners.get(event)?.push(listener)

    return this
  }

  off<K extends keyof E>(
    event: K,
    listener?: (value: E[K]) => void
  ): this {
    if (!this.listeners.has(event)) {
      return this
    }

    if (listener) {
      this.listeners.get(event)?.splice(
        this.listeners.get(event)?.indexOf(listener),
        1
      )
    } else {
      this.listeners.delete(event)
    }

    return this
  }

  emit<K extends keyof E>(event: K, value: E[K]): boolean {
    if (!this.listeners.has(event)) {
      return false
    }

    for (const listener of this.listeners.get(event)!) {
      listener(value)
    }

    return true
  }
}

